/* Follow a frame map (rules.h, generated by gen.py from the machine's Lean `next`) from its start frame.
   build: gcc -O2 -DRULES='"rules.h"' -DSTART_C=<ctor index> -DSTART_A='{a,b,c}' -o frames frames.c
   usage: frames MAXFRAMES [print|plain]   print = every frame, unaccelerated (to compare with gen.py's reference);
   plain = unaccelerated, final frame only.

   Acceleration. From a frame, up to KMAX rules are applied. If the frame comes back to its constructor and every
   rule used is a shift (each argument = own argument + constant, same position), the round trip adds a constant
   vector d. Positions where any rule of the cycle tests a literal must have d = 0. At every frame of the cycle,
   each position with d != 0 must stay at or above T(constructor), one more than every number in that
   constructor's patterns: there every pattern test is constant, so the same rules fire again. The cycle is then
   repeated as often as that bound allows. Otherwise the computed steps are just kept. Values are checked for
   overflow (signed 64-bit). Halts (`none` rules) are reported with the frame number. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include RULES
#define KMAX 6
typedef long long i64;
typedef unsigned __int128 u128;
static i64 T[NC];
static int findrule(int c, const i64 *a) {
  for (int k = 0; k < NR; k++) {
    if (RU[k].c != c) continue;
    int ok = 1;
    for (int i = 0; i < AR[c] && ok; i++) ok = RU[k].lit[i] ? a[i] == RU[k].pat[i] : a[i] >= RU[k].pat[i];
    if (ok) return k;
  }
  fprintf(stderr, "no rule\n"); exit(2);
}
static int isshift(int k) {
  int c = RU[k].c, oc = RU[k].oc;
  if (oc < 0 || AR[oc] != AR[c]) return 0;
  for (int o = 0; o < AR[c]; o++) for (int i = 0; i < AR[c]; i++)
    if (RU[k].cf[o][i] != (i == o && !RU[k].lit[o] ? 1 : 0)) return 0;
  return 1;
}
static void apply(int k, const i64 *a, i64 *b) {
  int c = RU[k].c, oc = RU[k].oc; i64 v[NA];
  for (int i = 0; i < AR[c]; i++) v[i] = RU[k].lit[i] ? 0 : a[i] - RU[k].pat[i];
  for (int o = 0; o < AR[oc]; o++) {
    __int128 s = RU[k].cst[o];
    for (int i = 0; i < AR[c]; i++) s += (__int128)RU[k].cf[o][i] * v[i];
    if (s > ((i64)1 << 61)) { printf("overflow\n"); exit(3); }
    b[o] = (i64)s;
  }
}
static int c; static i64 a[NA]; static u128 frames;
static void halt(void) {
  printf("HALT at frame %.0f: %s", (double)frames, CN[c]); for (int i = 0; i < AR[c]; i++) printf(" %lld", a[i]);
  printf("\n"); exit(0);
}
int main(int argc, char **argv) {
  double maxf = atof(argv[1]); int print = argc > 2, plain = argc > 2 && !strcmp(argv[2], "plain");
  for (int k = 0; k < NR; k++) for (int i = 0; i < AR[RU[k].c]; i++) if (RU[k].pat[i] + 1 > T[RU[k].c]) T[RU[k].c] = RU[k].pat[i] + 1;
  i64 st0[NA] = START_A; c = START_C; memcpy(a, st0, sizeof a);
  i64 mx = 0; u128 visits = 0, bulk = 0; time_t t0 = time(0); double next_rep = 1e6;
  while ((double)frames < maxf) {
    if (print) {
      if (!plain) { printf("%llu %s", (unsigned long long)frames, CN[c]); for (int i = 0; i < AR[c]; i++) printf(" %lld", a[i]); printf("\n"); }
      int k = findrule(c, a); if (RU[k].oc < 0) halt();
      i64 b[NA]; apply(k, a, b); c = RU[k].oc; memcpy(a, b, sizeof a); frames++; continue;
    }
    /* try a cycle of length <= KMAX */
    int cs[KMAX + 1]; i64 vs[KMAX + 1][NA]; int ks[KMAX]; int n = 0, shift = 1, found = 0;
    cs[0] = c; memcpy(vs[0], a, sizeof a);
    while (n < KMAX) {
      int k = findrule(cs[n], vs[n]);
      if (RU[k].oc < 0) { if (n) { c = cs[n]; memcpy(a, vs[n], sizeof a); frames += n; } halt(); }
      ks[n] = k; if (!isshift(k)) shift = 0;
      apply(k, vs[n], vs[n + 1]); cs[n + 1] = RU[k].oc; n++;
      if (cs[n] == cs[0] && shift) { found = 1; break; }
      if (!shift) break;
    }
    u128 N = 1;
    if (found) {
      i64 d[NA]; int ok = 1;
      for (int i = 0; i < AR[c]; i++) d[i] = vs[n][i] - vs[0][i];
      for (int p = 0; p < n && ok; p++) for (int i = 0; i < AR[c]; i++) if (RU[ks[p]].lit[i] && d[i]) ok = 0;
      if (ok) {
        i64 lim = (i64)1 << 40;
        for (int p = 0; p < n && ok; p++) for (int i = 0; i < AR[c]; i++) {
          if (!d[i]) continue;
          if (vs[p][i] < T[cs[p]]) { ok = 0; break; }
          if (d[i] < 0) { i64 m = (vs[p][i] - T[cs[p]]) / (-d[i]); if (m < lim) lim = m; }
        }
        if (ok) {
          N = (u128)lim + 1;
          for (int i = 0; i < AR[c]; i++) { a[i] = vs[0][i] + d[i] * (i64)N; if (a[i] > ((i64)1 << 61)) { printf("overflow\n"); return 3; } }
          frames += N * n; bulk++;
        }
      }
      if (!ok) found = 0;
    }
    if (!found) { c = cs[n]; memcpy(a, vs[n], sizeof a); frames += n; }
    visits++;
    for (int i = 0; i < AR[c]; i++) if (a[i] > mx) mx = a[i];
    if ((double)frames >= next_rep) {
      fprintf(stderr, "frames %.3e visits %.3e bulk %.3e max %lld  %lds\n", (double)frames, (double)visits, (double)bulk, mx, (long)(time(0) - t0));
      next_rep *= 10;
    }
  }
  printf("no halt in %.3e frames; max argument %lld; last (frame %llu) %s", (double)frames, mx, (unsigned long long)frames, CN[c]);
  for (int i = 0; i < AR[c]; i++) printf(" %lld", a[i]);
  printf("\n");
  return 1;
}
